const extracted = $input.first().json.data || $input.first().json;
const needsReviewReasons = [];

if (!extracted.project_reference || extracted.project_reference.toLowerCase().includes('unknown')) {
  needsReviewReasons.push('Missing or unrecognized Construction Project reference in vendor submission.');
}
if (!extracted.document_reference) {
  needsReviewReasons.push('Missing invoice/receipt document reference.');
}
if (Number(extracted.amount || 0) <= 0) {
  needsReviewReasons.push('Missing or zero invoice amount.');
}

return [{
  json: {
    ...extracted,
    pre_check_needs_clarification: needsReviewReasons.length > 0,
    pre_check_reasons: needsReviewReasons
  }
}];

const res = $input.first().json.data;
return [{
  json: {
    status: 'FLAGGED_FOR_REVIEW',
    action_taken: res.action,
    alert_routed_to: 'kevin@kevinconstruction.com',
    notion_url: res.cost?.notion_url,
    clarification_notes: res.cost?.clarification_notes,
    cost: res.cost
  }
}];

const res = $input.first().json.data;
return [{
  json: {
    status: 'RECORDED_OR_UPDATED_CLEANLY',
    action_taken: res.action,
    duplicate_prevented: res.duplicate_prevented,
    alert_routed_to: res.cost?.notified_person || 'marcus.vance@kevinconstruction.com',
    notion_url: res.cost?.notion_url,
    cost: res.cost
  }
}];
